node --experimental-sqlite -e "
const { DatabaseSync } = require('node:sqlite');
const db = new DatabaseSync('/workspace/world.db');

// 1. Shift the 'Lunch with Jordan' reminder from 1788260400.0 to 1788269400.0
const update = db.prepare(\"UPDATE ts_reminders SET reminder_timestamp = 1788269400.0 WHERE reminder_id = 'a9e934a7-a20f-4401-a151-6c178b4c43d4'\");
const result = update.run();
console.log('Update result:', JSON.stringify(result));

// 2. Create the new reminder for 'Follow up with Maya if she\\'s not there by 6:30 PM.'
const crypto = require('crypto');
const newId = crypto.randomUUID();
const now = Date.now() / 1000;
const insert = db.prepare(\"INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp) VALUES (?, ?, ?, ?)\");
const insertResult = insert.run(newId, \"Follow up with Maya if she's not there by 6:30 PM.\", now, 1788269400.0);
console.log('Insert result:', JSON.stringify(insertResult));
console.log('New reminder ID:', newId);

// Verify
const reminders = db.prepare('SELECT * FROM ts_reminders WHERE reminder_id IN (?, ?)', ).all();
console.log('---');
const jordan = db.prepare(\"SELECT * FROM ts_reminders WHERE reminder_id = 'a9e934a7-a20f-4401-a151-6c178b4c43d4'\").get();
console.log('Jordan reminder:', JSON.stringify(jordan, null, 2));
const maya = db.prepare(\"SELECT * FROM ts_reminders WHERE reminder_id = ?\").get(newId);
console.log('Maya reminder:', JSON.stringify(maya, null, 2));
